INSERT INTO platforms ("id", "slug", "name", "company", "website", "logoUrl", "description", "categoryId", "primaryUse", "costTier", "difficultyLevel", "platformType", "currentPricing", "freeTierFeatures", "usageLimits", "qualityRestrictions", "upgradeTriggers", "installationType", "offlineCapable", "apiAvailable", "keyIntegrations", "privacyLevel", "idealUserTypes", "primaryUseCases", "timeToProductivity", "learningCurve", "directAlternatives", "complementaryTools", "budgetAlternativeTo", "privacyAlternativeTo", "contentTypes", "outputFormats", "languageSupport", "featured", "verified", "createdAt", "updatedAt", "hasMobileApp", "iosAppUrl", "androidAppUrl", "mobileWebFriendly") SELECT $xw$cmxmagi2x2026112600001$xw$, $xw$magi-2$xw$, $xw$MAGI-2$xw$, $xw$Sand AI$xw$, $xw$https://sand.ai/$xw$, NULL, $xw$Sand AI's MAGI-2 is a video model. The research post dated November 24, 2026 says it has 480 billion total parameters and about 28 billion active parameters, and the scaling section also says 28 billion active. It generates up to 30 seconds of 1080p, 25 fps video with native audio. The post says open-source releases will follow. That is a promise, not a release. The platform pricing page lists model magi-2 at 1080p for 0.08 USD per second. That page does not state an end date or a free tier, and it says top-up is not supported for the time being. The balance and billing page describes opening Top up and paying online. Both pages were read on 2026-11-26. sand.ai introduces MAGI-2, and magi.sand.ai redirects there. A playground page exists at platform.sand.ai/app/playground/. The homepage links to vidmuse.ai/en/magi-2, and that page was not readable on 2026-11-26.$xw$, $xw$cmnxhffxh000n88svxrjl7o5e$xw$, $xw$Video model for clips up to 30 seconds at 1080p with native audio$xw$, $xw$PAID$xw$::"CostTier", $xw$INTERMEDIATE$xw$::"Difficulty", ARRAY[$xw$api$xw$, $xw$web$xw$]::text[], $xw$API, model magi-2 at 1080p: 0.08 USD per second. The pricing page does not state an end date or a free tier (as of 2026-11-26)$xw$, $xw$The model pricing page does not state a free tier (as of 2026-11-26)$xw$, $xw$Up to 30 seconds at 1080p and 25 fps with native audio, per the November 24, 2026 research post$xw$, NULL, $xw$The pricing page lists one 1080p rate and does not price another resolution$xw$, $xw$Sand AI Platform API, model id magi-2, and the playground at platform.sand.ai/app/playground/$xw$, false, true, NULL, $xw$MEDIUM$xw$::"PrivacyLevel", ARRAY[$xw$developers$xw$, $xw$video creators$xw$]::text[], $xw$Generating a clip with sound from a prompt through the Sand AI Platform API$xw$, NULL, $xw$Moderate$xw$, ARRAY[$xw$Kling AI$xw$, $xw$Runway$xw$, $xw$Pika$xw$]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[$xw$Text$xw$, $xw$Images$xw$, $xw$Video$xw$, $xw$Audio$xw$]::text[], ARRAY[$xw$Video with native audio$xw$]::text[], $xw$Languages beyond the English pages were not stated (as of 2026-11-26)$xw$, false, true, now(), now(), false, NULL, NULL, true WHERE NOT EXISTS (SELECT 1 FROM platforms WHERE slug = $xw$magi-2$xw$) AND EXISTS (SELECT 1 FROM categories WHERE id = $xw$cmnxhffxh000n88svxrjl7o5e$xw$ AND slug = $xw$video-creation-editing$xw$);
